/// `contacts.count`
#[must_use]
pub fn contacts_count(l: Locale, count: i64) -> String {
    match l {
        Locale::En => {
            if count == 1 {
                format!("{} contact", district_core::l10n::format::integer(l, count))
            } else {
                format!("{} contacts", district_core::l10n::format::integer(l, count))
            }
        }
        Locale::FrCa => {
            if count == 0 || count == 1 {
                format!("{} contact", district_core::l10n::format::integer(l, count))
            } else {
                format!("{} contacts", district_core::l10n::format::integer(l, count))
            }
        }
    }
}

