/// `directory.incomplete_note`
#[must_use]
pub fn directory_incomplete_note(l: Locale, count: i64) -> String {
    match l {
        Locale::En => {
            if count == 1 {
                "One entry lacks a name or a number. It is kept, but the receptionist cannot put anyone through to it.".to_owned()
            } else {
                format!("{} entries lack a name or a number. They are kept, but the receptionist cannot put anyone through to them.", district_core::l10n::format::integer(l, count))
            }
        }
        Locale::FrCa => {
            if count == 0 || count == 1 {
                format!("{} entrée est sans nom ou sans numéro. Elle est conservée, mais la réceptionniste ne peut pas y transférer d'appels.", district_core::l10n::format::integer(l, count))
            } else {
                format!("{} entrées sont sans nom ou sans numéro. Elles sont conservées, mais la réceptionniste ne peut pas y transférer d'appels.", district_core::l10n::format::integer(l, count))
            }
        }
    }
}

